    out_path = args.out or (transcript.parent / f"{session_id}.messages.json")
    out_path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "session_id": session_id,
        "cwd": str(cwd),
        "catalog": str(catalog),
        "messages": messages,
    }
    out_path.write_text(json.dumps(payload, indent=2))

    view = []
    for m in messages:
        text = m["message"]
        if args.max_chars and len(text) > args.max_chars:
            text = text[: args.max_chars] + f"... [truncated, {len(m['message'])} chars]"
        view.append({"uuid": m["uuid"], "role": m["role"], "text": text})

    print(
        json.dumps(
            {
                "session_id": session_id,
                "messages_file": str(out_path),
                "already_labeled": len(seen),
                "to_label": len(messages),
                "messages": view,
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

