    if problems:
        print("Rejected:", file=sys.stderr)
        for problem in problems:
            print(f"  {problem}", file=sys.stderr)

    unlabeled = set(messages) - {r["uuid"] for r in records} - already
    if unlabeled:
        print(f"No label supplied for {len(unlabeled)} message(s)", file=sys.stderr)

