            match = re.match(r"^- `([a-z0-9-]+)`", line)
            if match:
                domains.add(match.group(1))
        elif section == "tags":
            tags.update(re.findall(r"`([a-z0-9-]+)`", line))
    if not domains or not tags:
        sys.exit(f"Could not parse the vocabulary from {path}")
    return domains, tags


def validate(label: dict, domains: set[str], tags: set[str]) -> list[str]:
    errors = []
    domain = label.get("domain")
    if domain is not None and domain not in domains:
        errors.append(f"unknown domain {domain!r}")

    label_tags = label.get("tags", [])
    if not isinstance(label_tags, list):
        errors.append("tags must be a list")
        return errors
    if len(label_tags) > MAX_TAGS:
        errors.append(f"{len(label_tags)} tags, max is {MAX_TAGS}")
    for tag in label_tags:
        if tag.startswith("new:"):
            continue
        if tag not in tags:
            errors.append(f"unknown tag {tag!r}")

    if domain is None and label_tags:
        errors.append("tags given without a domain")
    if domain is not None and not label_tags:
        errors.append("domain given without tags")
    return errors


def existing_uuids(catalog: Path) -> set[str]:
    if not catalog.exists():
        return set()
    seen = set()
    with catalog.open() as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                seen.add(json.loads(line)["uuid"])
            except (json.JSONDecodeError, KeyError):
                continue
    return seen


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("labels", nargs="?", type=Path, help="JSON file; omit to read stdin")
    parser.add_argument("--messages", type=Path, required=True, help="messages.json from extract")
    parser.add_argument("--catalog", type=Path, help="Override the catalog path")
    args = parser.parse_args()

    raw = args.labels.read_text() if args.labels else sys.stdin.read()
    try:
        labels = json.loads(raw)
    except json.JSONDecodeError as exc:
        sys.exit(f"Labels are not valid JSON: {exc}")
    if not isinstance(labels, list):
        sys.exit("Labels must be a JSON array of {uuid, domain, tags}")

    payload = json.loads(args.messages.read_text())
    messages = {m["uuid"]: m for m in payload["messages"]}
    catalog = args.catalog or Path(payload["catalog"])

    domains, tags = load_vocabulary(TAXONOMY)
    already = existing_uuids(catalog)

    records, problems, skipped = [], [], 0
    attempted = set()
    for label in labels:
        uuid = label.get("uuid")
        attempted.add(uuid)
        if uuid not in messages:
            problems.append(f"{uuid}: not in the extracted messages")
            continue
        if uuid in already:
            skipped += 1
            continue
        errors = validate(label, domains, tags)
        if errors:
            problems.append(f"{uuid}: " + "; ".join(errors))
            continue
        message = messages[uuid]
        records.append(
            {
                "uuid": uuid,
                "username": message["username"],
                "role": message["role"],
                "domain": label.get("domain"),
                "tags": label.get("tags", []),
                "message": message["message"],
            }
        )
        already.add(uuid)

    if problems:
        print("Rejected:", file=sys.stderr)
        for problem in problems:
            print(f"  {problem}", file=sys.stderr)

    unlabeled = set(messages) - {r["uuid"] for r in records} - already
    if unlabeled:
        print(f"No label supplied for {len(unlabeled)} message(s)", file=sys.stderr)

    if records:
        catalog.parent.mkdir(parents=True, exist_ok=True)
        with catalog.open("a") as f:
            for record in records:
                f.write(json.dumps(record, ensure_ascii=False) + "\n")

    print(f"Wrote {len(records)} record(s) to {catalog}")
    if skipped:
        print(f"Skipped {skipped} already-labeled message(s)")
    if problems:
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Extract the labelable messages from a Claude Code session transcript.

Keeps human prompts and assistant text replies; drops attachments, tool calls,
tool results, thinking blocks and bookkeeping records. Messages already present
in the session's catalog are skipped, so a second run only returns what is new.

Writes the full messages (untruncated) to a JSON file for write_labels.py, and
prints a compact view to stdout for the model to label.
"""

import argparse
import json
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

CATALOG_ROOT = Path.home() / ".claude" / "labeled"
PROJECTS_ROOT = Path.home() / ".claude" / "projects"

# Editor and harness context wrapped around a prompt is not part of what the
# user said, and an <ide_selection> blob dwarfs most messages.
NOISE_BLOCKS = re.compile(
    r"<(ide_selection|ide_opened_file|ide_diagnostics|system-reminder)>.*?</\1>",
    re.DOTALL,
)


def escape_project(cwd: Path) -> str:
    """Mirror Claude Code's own project directory naming: / becomes -."""
    return str(cwd).replace("/", "-")


def resolve_transcript(cwd: Path, session: str | None, transcript: Path | None) -> Path:
    if transcript:
        return transcript
    project_dir = PROJECTS_ROOT / escape_project(cwd)
    if session:
        return project_dir / f"{session}.jsonl"
    candidates = sorted(
        project_dir.glob("*.jsonl"), key=lambda p: p.stat().st_mtime, reverse=True
    )
    if not candidates:
        sys.exit(f"No transcripts found in {project_dir}")
    return candidates[0]


def resolve_username(cwd: Path) -> str:
    for args in (["git", "config", "user.name"], ["git", "config", "user.email"]):
        try:
            out = subprocess.run(
                args, cwd=cwd, capture_output=True, text=True, timeout=5
            )
        except (OSError, subprocess.SubprocessError):
            continue
        if out.returncode == 0 and out.stdout.strip():
            return out.stdout.strip()
    return os.environ.get("USER", "unknown")


def already_labeled(catalog: Path) -> set[str]:
    """uuids already written for this session — the catalog is its own state."""
    if not catalog.exists():
        return set()
    seen = set()
    with catalog.open() as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                seen.add(json.loads(line)["uuid"])
            except (json.JSONDecodeError, KeyError):
                continue
    return seen


def user_text(record: dict) -> str | None:
    """Text of a human prompt, or None if this user record is not one."""
    if record.get("origin", {}).get("kind") != "human":
        return None
    if record.get("toolUseResult") or record.get("isMeta") or record.get("turnCompanion"):
        return None
    blocks = record.get("message", {}).get("content", [])
    if isinstance(blocks, str):
        return clean(blocks)
    parts = [b.get("text", "") for b in blocks if b.get("type") == "text"]
    return clean("\n\n".join(p for p in parts if p))


def clean(text: str) -> str | None:
    text = NOISE_BLOCKS.sub("", text).strip()
    return text or None


def assistant_text(record: dict) -> str | None:
    """Text of one assistant content block, or None if it is not a text block."""
    if record.get("isSidechain"):
        return None
    blocks = record.get("message", {}).get("content", [])
    if isinstance(blocks, str):
        return blocks.strip() or None
    parts = [b.get("text", "") for b in blocks if b.get("type") == "text"]
    return "\n\n".join(p for p in parts if p).strip() or None


def extract(transcript: Path, username: str) -> list[dict]:
    """One record per human prompt and per assistant reply, in transcript order.

    An assistant reply arrives split across several lines, one per content block,
    sharing a requestId and ordered by apiBlockIndex. Those are joined back into
    a single message keyed by the first block's uuid.
    """
    messages: list[dict] = []
    assistant_index: dict[str, int] = {}

    with transcript.open() as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError:
                continue

            kind = record.get("type")
            if kind == "user":
                text = user_text(record)
                if text:
                    messages.append(
                        {
                            "uuid": record["uuid"],
                            "role": "user",
                            "username": username,
                            "message": text,
                        }
                    )
            elif kind == "assistant":
                text = assistant_text(record)
                if not text:
                    continue
                request_id = record.get("requestId") or record["uuid"]
                if request_id in assistant_index:
                    pos = assistant_index[request_id]
                    messages[pos]["message"] += "\n\n" + text
                else:
                    assistant_index[request_id] = len(messages)
                    messages.append(
                        {
                            "uuid": record["uuid"],
                            "role": "assistant",
                            "username": username,
                            "message": text,
                        }
                    )

    return messages


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--session", help="Session id; defaults to the newest transcript")
    parser.add_argument("--transcript", type=Path, help="Explicit transcript path")
    parser.add_argument("--cwd", type=Path, default=Path.cwd(), help="Project directory")
    parser.add_argument("--out", type=Path, help="Where to write the full messages JSON")
    parser.add_argument(
        "--max-chars",
        type=int,
        default=2000,
        help="Truncation applied to the stdout view only (0 disables)",
    )
    args = parser.parse_args()

    cwd = args.cwd.resolve()
    transcript = resolve_transcript(cwd, args.session, args.transcript)
    if not transcript.exists():
        sys.exit(f"Transcript not found: {transcript}")

    session_id = transcript.stem
    catalog = CATALOG_ROOT / escape_project(cwd) / f"{session_id}.jsonl"
    seen = already_labeled(catalog)

    username = resolve_username(cwd)
    messages = [m for m in extract(transcript, username) if m["uuid"] not in seen]

    out_path = args.out or (
        Path(tempfile.gettempdir()) / "tag-session" / f"{session_id}.messages.json"
    )
    out_path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "session_id": session_id,
        "cwd": str(cwd),
        "catalog": str(catalog),
        "messages": messages,
    }
    out_path.write_text(json.dumps(payload, indent=2))

    view = []
    for m in messages:
        text = m["message"]
        if args.max_chars and len(text) > args.max_chars:
            text = text[: args.max_chars] + f"... [truncated, {len(m['message'])} chars]"
        view.append({"uuid": m["uuid"], "role": m["role"], "text": text})

    print(
        json.dumps(
            {
                "session_id": session_id,
                "messages_file": str(out_path),
                "already_labeled": len(seen),
                "to_label": len(messages),
                "messages": view,
            },
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

